window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"rXg7QGRaLuo","speaker":"Abdullah Abdulkader Al Alimi-Bawzer","role":"Vice President","country":"Yemen","region":"Middle East","url":"https://www.youtube.com/watch?v=rXg7QGRaLuo","date":"20260924","title":"🇾🇪 Yemen - Vice President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1265,"words":2347,"counts":{"claims":31,"promises":1,"attacks":8},"topics":[{"topic":"Iran","share":0.1742,"seconds":220},{"topic":"Yemen conflict","share":0.1497,"seconds":189},{"topic":"Yemen peace","share":0.1066,"seconds":135},{"topic":"Yemen terrorism","share":0.1002,"seconds":127},{"topic":"Yemen state restoration","share":0.0991,"seconds":125},{"topic":"Yemen sovereignty","share":0.0722,"seconds":91},{"topic":"Yemen future","share":0.0519,"seconds":66},{"topic":"Yemen Saudi partnership","share":0.0503,"seconds":64},{"topic":"Yemen security","share":0.0502,"seconds":64},{"topic":"Yemen crisis","share":0.0496,"seconds":63},{"topic":"Red Sea security","share":0.0485,"seconds":61},{"topic":"Yemen armed forces","share":0.0474,"seconds":60}],"timeline":[[3,66,"Yemen crisis"],[68,129,"Yemen conflict"],[131,195,"Yemen conflict"],[196,257,"Iran"],[258,322,"Yemen terrorism"],[323,400,"Iran"],[403,485,"Iran"],[487,548,"Red Sea security"],[549,612,"Yemen security"],[614,678,"Yemen state restoration"],[680,745,"Yemen peace"],[747,807,"Yemen armed forces"],[807,868,"Yemen state restoration"],[869,935,"Yemen future"],[937,999,"Yemen terrorism"],[1002,1065,"Yemen Saudi partnership"],[1067,1131,"Yemen conflict"],[1134,1203,"Yemen peace"],[1204,1265,"Yemen sovereignty"],[1265,1296,"Yemen sovereignty"]],"stances":{"Yemen crisis":"Abdullah Abdulkader Al Alimi-Bawzer states that while 12 years is a short time in politics, it represents an entire childhood for a Yemeni child.","Yemen conflict":"The speaker describes the severe impact of 12 years of conflict on Yemeni children and calls for international support to restore state stability.","Iran":"The speaker asserts that the Houthi militias' escalation in the Red Sea is driven by an Iranian agenda and sustained by Iranian expertise and technology.","Yemen terrorism":"The speaker argues that the international community's hesitation to designate the Houthis as a terrorist group allowed them to expand, and supports firm action including US administration measures and Saudi-led coalition efforts.","Red Sea security":"The speaker argues that maritime security in the Red Sea cannot be achieved while non-state armed militias operate on the shores and highlights growing cooperation between these militias and terrorist organizations.","Yemen security":"The speaker asserts that restoring the Yemeni state and securing the Bab el-Mandeb strait are inseparable issues requiring international support.","Yemen state restoration":"The speaker asserts that restoring the Yemeni state is essential for regional security and stability, as peace cannot be achieved while armed militias operate outside state authority.","Yemen peace":"The speaker asserts that the government is committed to peace but rejects armed coups outside state authority, emphasizing that 12 years of conflict have caused severe human suffering.","Yemen armed forces":"The speaker salutes the Yemeni armed forces for confronting Houthi militias and affirms their role in defending the country's sovereignty.","Yemen future":"Abdullah Abdulkader Al Alimi-Bawzer advocates for a post-war Yemen that is safe, stable, and prosperous, emphasizing inclusive nation-building rather than external military intervention.","Yemen Saudi partnership":"Abdullah Abdulkader Al Alimi-Bawzer expresses a commitment to fulfilling Yemen's responsibilities in reform and institution building while highlighting the importance of Saudi Arabia's support for Yemen's security and stability.","Yemen sovereignty":"The speaker reaffirms Yemen's commitment to its revolutionary values and asserts that the country belongs to its free people, explicitly excluding Iran and its proxies from ownership."},"claims":[{"t":54,"quote":"12 years could be in politics a mere temporal span, the length of a protracted crisis. But for a Yemeni child, 12 years are his entire childhood.","topic":"Yemen crisis","kind":"fact"},{"t":110,"quote":"Yemen, this great nation with its rich history, civilization, and human heritage has been enduring for 12 years.","topic":"Yemen conflict","kind":"fact"},{"t":121,"quote":"The consequences of the coup carried out by the terrorist Houthi militia against the state and its 12 years.","topic":"Yemen conflict","kind":"fact"},{"t":131,"quote":"12 years marked by war, displacement, poverty, recruitment of children, terrorizing of women, laying of mines, confiscation of rights, freedoms and public resources.","topic":"Yemen conflict","kind":"fact"},{"t":148,"quote":"the government of Yemen has engaged responsibly and positively with all international and regional initiatives and has made significant in pursuit of peace and an end to the suffering of the Yemeni people.","topic":"Yemen conflict","kind":"self_credit"},{"t":200,"quote":"the Houthi militias rejected it and instead escalated their actions in the Red Sea and Babel Mandab to serve an Iranian agenda that goes beyond the interests of Yemen and its people.","topic":"Iran","kind":"fact"},{"t":232,"quote":"this coup could not have persisted for so many years. Nor could its threat have expanded from Yemen to neighboring states and international waterways without the expertise and technology provided to the Houthi militias by the rogue Iranian regime.","topic":"Iran","kind":"fact"},{"t":258,"quote":"The intern the international community's hesitation to designate the Houthis as a terrorist group provided them with a valuable opportunity to expand their influence and magnify the threat they pose.","topic":"Yemen terrorism","kind":"fact"},{"t":270,"quote":"We have seen that decisive action when applied weakens their capabilities.","topic":"Yemen terrorism","kind":"fact"},{"t":345,"quote":"An international resolution without a political will to implement it does not stop wars. Rather, it merely prolongs a marathon of negotiations while only terrorism advances.","topic":"Iran","kind":"fact"},{"t":373,"quote":"Ladies and gentlemen, Iranian support is not the only factor contributing to the danger posed by healthy terrorist militias.","topic":"Iran","kind":"fact"},{"t":403,"quote":"In Yemen, we're not confronting a purely local terrorist militia. Rather, we face an extension of the Iranian Revolutionary Guard Corps with which which is also using terrorist groups to threaten international peace","topic":"Iran","kind":"fact"},{"t":438,"quote":"Recent years have clearly demonstrated a truth that the international community must not dismiss, namely that ensuring security at sea begins with eliminating the source of the threat on land.","topic":"Iran","kind":"fact"},{"t":520,"quote":"International reports have exposed growing cooperation between the terrorist healthy militias and terrorist organizations including in the Horn of Africa through networks linking militias, terrorist groups, smugglers and organized crime networks thereby undermining states and threatening security and stability.","topic":"Red Sea security","kind":"fact"},{"t":559,"quote":"restoring the Yemen state and restoring the security of Babel Mandab are inseparable. They are not two separate issues but one and the same.","topic":"Yemen security","kind":"fact"},{"t":582,"quote":"Protecting this strategic waterway is a shared regional and international responsibility which Yemen cannot shoulder alone.","topic":"Yemen security","kind":"fact"},{"t":637,"quote":"There is no stability in Yemen without restoring the state.","topic":"Yemen state restoration","kind":"fact"},{"t":644,"quote":"Sustainable peace cannot be achieved while an armed militia remains above the law and outside state authority.","topic":"Yemen state restoration","kind":"fact"},{"t":703,"quote":"12 years of an incomplete peace have left millions millions of people enduring hunger, injuries, displacement.","topic":"Yemen peace","kind":"number"},{"t":747,"quote":"Today, the heroes of the Yemeni armed forces and all military formations, legitimate military formations are on the ground confronting these Houthi terrorist militias in defense of our people, our land, our sovereignty, and our future.","topic":"Yemen armed forces","kind":"fact"},{"t":827,"quote":"Our struggle is against an armed coup that has taken hostage the state and its institutions that deepened the suffering of uh Yemen and Yemenes to serve Iran and its schemes.","topic":"Yemen state restoration","kind":"fact"},{"t":887,"quote":"We seek a safe, stable, prosperous Yemen that safeguards the dignity of its citizens, rebuilds its economy, provides education for its children, jobs for its youth, security for its families.","topic":"Yemen future","kind":"fact"},{"t":937,"quote":"They are determined to restore their state, rebuild its institutions, and confront terrorism in all its forms.","topic":"Yemen terrorism","kind":"fact"},{"t":962,"quote":"The Yemen government is capable of ending the threat posed by this terrorist group and protecting Yemen's ports and territorial","topic":"Yemen terrorism","kind":"fact"},{"t":1060,"quote":"The kingdom has borne and continues to bear significant burdens in support of Yemen's security and stability.","topic":"Yemen Saudi partnership","kind":"fact"},{"t":1072,"quote":"the Republic of Yemen condemns the terrorist attacks carried out by the Houthi militias against the kingdom targeting its territory, facilities, and resources.","topic":"Yemen conflict","kind":"fact"},{"t":1083,"quote":"We equally condemn their attempted targeting of Mecca al- Mukar to which the hearts and prayers of Muslims turn.","topic":"Yemen conflict","kind":"fact"},{"t":1156,"quote":"we condemn the continued detention by the Houthi militias of UN personnel and humanitarian humanitarian workers.","topic":"Yemen peace","kind":"fact"},{"t":1187,"quote":"I extend my congratulations to our great Yemeni people at home and abroad on the occasion today on the occasion of the 60 of the anniversary of the revolution of the 26th of September.","topic":"Yemen peace","kind":"fact"},{"t":1223,"quote":"Babel Mandab Bab al-Mandab will remain as geography intended it to be, a bridge between peoples, a route for commerce and a gateway to peace.","topic":"Yemen sovereignty","kind":"fact"},{"t":1249,"quote":"Yemen belongs to its free people, not to Iran, nor to its proxies.","topic":"Yemen sovereignty","kind":"fact"}],"promises":[{"t":1009,"quote":"For our part, we will continue to fulfill our responsibilities in reform, institution building, and the rule of law.","topic":"Yemen Saudi partnership","kind":"promise"}],"attacks":[{"t":124,"quote":"the terrorist Houthi militia","topic":"Yemen conflict","target":"Houthi militia"},{"t":168,"quote":"However, the terrorist Houthi militias have responded to those efforts with intrigence using periods of humanitarian truses to advance their military arsenals at the expense of the livelihoods of ordinary citizens.","topic":"Yemen conflict","target":"Houthi militia"},{"t":382,"quote":"They also benefit from the lack of an effective and decisive international They benefit from every statement that underestimates the threat represented by this racist terrorist movement in Yemen.","topic":"Iran","target":"Houthi militia"},{"t":463,"quote":"Do not be reassured by false promises from a terrorist militia that has repeatedly made endless commitments just as it failed to honor Its abstension from targeting ships today does not mean at all it will not do so tomorrow.","topic":"Iran","target":"Houthi militia"},{"t":827,"quote":"Our struggle is against an armed coup that has taken hostage the state and its institutions that deepened the suffering of uh Yemen and Yemenes to serve Iran and its schemes.","topic":"Yemen state restoration","target":"Iran"},{"t":1074,"quote":"condemns the terrorist attacks carried out by the Houthi militias against the kingdom","topic":"Yemen conflict","target":"Houthi militia"},{"t":1156,"quote":"we condemn the continued detention by the Houthi militias of UN personnel and humanitarian humanitarian workers.","topic":"Yemen peace","target":"Houthi militia"},{"t":1251,"quote":"not to Iran, nor to its proxies.","topic":"Yemen sovereignty","target":"Iran"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":3,"topic":"Yemen crisis","text":"The assembly will now hear an address by His Excellency Abdullah Abdul Kader Alimi Baer, Vice President of the Presidential Leadership Council of the Republic of Yemen. I request protocol to escort his excellency and invite him to address the Your majesties, excellencies, highnesses, distin distinguished delegates, Mr. President of the General Assembly, Mr. Secretary Generals, ladies and gentlemen, 12 years could be in politics a mere temporal span, the length of a protracted crisis. But for a Yemeni child, 12 years are his entire childhood."},{"t":68,"topic":"Yemen conflict","text":"An entire generation was born amid war. Grew up amid hunger, fear, and weapons. Learning the names of minds before learning the alphabet of life. Today, we do not ask the world to mourn every Yemeni child whose future has been stolen. Rather, we ask how many more children must be deprived of their future before the world stands with the Yemeni people and their struggle to restore their state and their stability. The people of Yemen. Yemen, this great nation with its rich history, civilization, and human heritage has been enduring for 12 years. The consequences of the coup carried out by the terrorist Houthi militia against the state and its 12 years."},{"t":131,"topic":"Yemen conflict","text":"12 years marked by war, displacement, poverty, recruitment of children, terrorizing of women, laying of mines, confiscation of rights, freedoms and public resources. Ladies and gentlemen, the government of Yemen has engaged responsibly and positively with all international and regional initiatives and has made significant in pursuit of peace and an end to the suffering of the Yemeni people. However, the terrorist Houthi militias have responded to those efforts with intrigence using periods of humanitarian truses to advance their military arsenals at the expense of the livelihoods of ordinary citizens. The latest of these efforts was the initiative undertaken by the Kingdom of Saudi Arabia and the Sultanate of Oman to elaborate a road map toward peace."},{"t":196,"topic":"Iran","text":"The Yemeni government accepted that initiative while the Houthi militias rejected it and instead escalated their actions in the Red Sea and Babel Mandab to serve an Iranian agenda that goes beyond the interests of Yemen and its people. turning one of its of the world's most important waterways into a tool of pressure and bargaining that in Iran's confrontation with the Ladies and gentlemen, this coup could not have persisted for so many years. Nor could its threat have expanded from Yemen to neighboring states and international waterways without the expertise and technology provided to the Houthi militias by the rogue Iranian regime."},{"t":258,"topic":"Yemen terrorism","text":"The intern the international community's hesitation to designate the Houthis as a terrorist group provided them with a valuable opportunity to expand their influence and magnify the threat they pose. We have seen that decisive action when applied weakens their capabilities. The coalition to restore legitimacy in Yemen, led by the Kingdom of Saudi Arabia, has played a critical role in reducing the dangers posed by this group through its support for the Yemeni government, thereby regional international security and We believe that this firm approach adopted by the United States administration in dealing with the Houthi militias has disrupted their The Yemeni government appreciate President Trump's clear understanding of the only language this terrorist group comprehends, the language of resolve."},{"t":323,"topic":"Iran","text":"It is the language that leaves no room for We likewise value the support of every friendly state that has stood behind this position. International legitimacy and its resolutions are there. But resolutions alone do not make peace. An international resolution without a political will to implement it does not stop wars. Rather, it merely prolongs a marathon of negotiations while only terrorism advances. Peace is not a distant aspiration. It is a firm It is an effective deterrent action against those who threaten the security and stability of states. Ladies and gentlemen, Iranian support is not the only factor contributing to the danger posed by healthy terrorist militias. They also benefit from the lack of an effective and decisive international They benefit from every statement that underestimates the threat represented by this racist terrorist movement in Yemen."},{"t":403,"topic":"Iran","text":"In Yemen, we're not confronting a purely local terrorist militia. Rather, we face an extension of the Iranian Revolutionary Guard Corps with which which is also using terrorist groups to threaten international peace and The Houthi militia's use of the safety of navigation as a tool for blackmail threatened not only Yemen, it is taking hostage the entire global Recent years have clearly demonstrated a truth that the international community must not dismiss, namely that ensuring security at sea begins with eliminating the source of the threat on land. Protecting ships is important, but it only addresses the consequences and does not remove the threat. Therefore, we warn the world. Do not be reassured by false promises from a terrorist militia that has repeatedly made endless commitments just as it failed to honor Its abstension from targeting ships today does not mean at all it will not do so tomorrow."},{"t":487,"topic":"Red Sea security","text":"It is a strategic It is a strategic mistake to assume that maritime security can be sustained through asurances that can be walked A lasting maritime security in the Red Sea, Babel Mandab, and the Gulf of Aiden cannot be built while a non-state armed militia remains on the shores. Nor is the threat confined to Yemen and the Red Sea. International reports have exposed growing cooperation between the terrorist healthy militias and terrorist organizations including in the Horn of Africa through networks linking militias, terrorist groups, smugglers and organized crime networks thereby undermining states and threatening security and stability."},{"t":549,"topic":"Yemen security","text":"Ladies and we say with full confidence and we firmly believe that restoring the Yemen state and restoring the security of Babel Mandab are inseparable. They are not two separate issues but one and the same. Supporting the Yemeni government and strengthening its economic security and military cap capacities is an investment in international peace and security. Protecting this strategic waterway is a shared regional and international responsibility which Yemen cannot shoulder alone. It is the responsibility of every economy that depends on secure supply chains, energy security and freedom of navigation. In this regard, we commend the initiative of the Kingdom of Saudi Arabia to establish a multinational maritime defense coalition."},{"t":614,"topic":"Yemen state restoration","text":"This initiative reflects a deep appreciation and understanding of collective responsibility to protect navigation, deter threats, and combat smuggling. The path to a secure Red Sea requires a stable Yemen. There is no stability in Yemen without restoring the state. Sustainable peace cannot be achieved while an armed militia remains above the law and outside state authority. Restoring the Yemen state is restoring the Yemen state is not just a na national interest. It is a direct contribution to regional security and stability and to the protection of one of the world's most vital maritime corridors. Ladies and gentlemen, our Yemeni people aspires to peace."},{"t":680,"topic":"Yemen peace","text":"But our people will not abandon their state. Our government is committed to peace, but it cannot accept that the armed coup becomes a feta compli. There is no peace with arms outside state authority. Peace deeds, not words. 12 years of an incomplete peace have left millions millions of people enduring hunger, injuries, displacement. Every statistic in Yemen's tragedy carries a human story. The world must not become accustomed to this suffering. Yemen as a great country with its strategic location, its ports, its resources, its human capital. The challenge lies in unleashing those from the grip of war and transforming these capabilities into an engine for development."},{"t":747,"topic":"Yemen armed forces","text":"Today, the heroes of the Yemeni armed forces and all military formations, legitimate military formations are on the ground confronting these Houthi terrorist militias in defense of our people, our land, our sovereignty, and our future. Here from this very podium, I salute them. I salute their struggle. They stand today to prevent much greater harm from reaching this world. I also address a message to our people to our people in particular in Sah and and Ha and Huda and Damar in every governorate city and village under healthy control. We tell them from here, you are our people."},{"t":807,"topic":"Yemen state restoration","text":"Your suffering is our suffering. Your rights are our responsibility. You will never be outside the national project of a Yemen state nor outside its future. Our struggle is not against any Yemeni citizen nor against the sons of any region, governorate, any sect or social group. Our struggle is against an armed coup that has taken hostage the state and its institutions that deepened the suffering of uh Yemen and Yemenes to serve Iran and its schemes. Restoring the state is not a victory for one Yemeni party over another. It is the restoration of the rights of all Yemenes to their state and institutions. The Yemen for which we struggle belongs to all Yemenes. The state we seek to restore is your state."},{"t":869,"topic":"Yemen future","text":"The future of Yemen will not be built by excluding any of its sons. cause is not merely about how to end the war, but to build what comes after it. We seek a safe, stable, prosperous Yemen that safeguards the dignity of its citizens, rebuilds its economy, provides education for its children, jobs for its youth, security for its families. Yemen that's a partner for its neighbors, a responsible guardian of its strategic location, a bridge for trade and cooperation between the Arabian Peninsula, the HR of Africa and the wider world. That is the Yemen that we wish for the world to see. Not a Yemen of war, but a Yemen of statethood, of humanity, of opportunity, Yemen of the future. Ladies and the Yemeni people do not ask the world to fight their battle on their behalf."},{"t":937,"topic":"Yemen terrorism","text":"They are determined to restore their state, rebuild its institutions, and confront terrorism in all its forms. What we ask is that the international community fulfill its responsibilities, implement its resolutions, stop the flow of arms and technologies to the militias, support our national capacities and economy. The Yemen government is capable of ending the threat posed by this terrorist group and protecting Yemen's ports and territorial What we seek from the international community today is not a perpetual management of crisis, but a strategic partnership that promotes security, stability, and development for the benefit of Yemen, the region, and international peace and We do not ask the world to build Yemen's future for Yemenes."},{"t":1002,"topic":"Yemen Saudi partnership","text":"We seek a partnership that supports the state and its institutions and invests in Yemen's people. For our part, we will continue to fulfill our responsibilities in reform, institution building, and the rule of law. The international community can find in the Yemeni government a reliable partner. We speak not only of what women Yemen needs from the world, but also of what Yemen can contribute to the world once it regains its security and its stability. Ladies and gentlemen, we express our deep appreciation to the brotherly kingdom of Saudi Arabia for its unwavering support for Yemen, its people, and its government, and for the kingdom's comprehensive support to the state and its institutions. The kingdom has borne and continues to bear significant burdens in support of Yemen's security and stability."},{"t":1067,"topic":"Yemen conflict","text":"These efforts will remain firmly engraved in the memory of the Yemeni people. From this podium, the Republic of Yemen condemns the terrorist attacks carried out by the Houthi militias against the kingdom targeting its territory, facilities, and resources. We equally condemn their attempted targeting of Mecca al- Mukar to which the hearts and prayers of Muslims turn. We stand in solidarity with the kingdom and reaffirm Yemen's steadfast support for the kingdom's right to defend its territory, its citizens, and its national interests. Ladies and gentlemen, the Republic of Yemen reaffirms its unwavering support for the Palestinian people's right to freedom, dignity, and the establishment of their independent sovereign state in accordance with international resolutions and the Arab peace initiative. We call for ending the suffering of the Palestinian people, protecting civilians, and promoting stability in this world."},{"t":1134,"topic":"Yemen peace","text":"We equally express our appreciation to the United Nations, the secretary general and his special envoy, as well as all UN agencies for their support for their efforts rather in support of peace and in assistance to the Yemen people. and we value the support of friends and partners standing by the Yemeni people. At the same time, we condemn the continued detention by the Houthi militias of UN personnel and humanitarian humanitarian workers. Those working for peace and humanitarian relief must never be held hostage of I wish all the peoples of the world prosperity, peace and development and we hope for a world that is more secure, just, stable and prosperous. And in I extend my congratulations to our great Yemeni people at home and abroad on the occasion today on the occasion of the 60 of the anniversary of the revolution of the 26th of September."},{"t":1204,"topic":"Yemen sovereignty","text":"We reaffirm our commitment to the values and of the September and October revolutions and to the principles of our national struggle. principles that are non-negotiable. With determination of the Yemenes, their sacrifices and perseverance, Yemen will regain its security and its stability. Babel Mandab Bab al-Mandab will remain as geography intended it to be, a bridge between peoples, a route for commerce and a gateway to peace. Allow me to conclude this statement with words by a Yemeni poet expressing faith in the Yemeni people, Yemeni homeland in future and affirming that Yemen belongs to its free people, not to Iran, nor to its proxies. He said, \"We are the land, its custodians and its inhabitants. To us it belongs for we are its people and its home."},{"t":1265,"topic":"Yemen sovereignty","text":"Today belongs to the people. In yesterday the glorious yesterday belongs to them as well. To them belong the future, history and time itself. Long live Yemen, free, secure and great. May the peace and blessings be upon you On behalf of the general assembly, I wish to thank the vice president of the presidential leadership council of the republic of Yemen."}],"compare":[{"topic":"Yemen","share":0.2722,"mean":0.0023,"rank":1,"others":4},{"topic":"Iran","share":0.1742,"mean":0.0129,"rank":4,"others":25},{"topic":"Red Sea","share":0.0485,"mean":0.0011,"rank":4,"others":3}]};
